                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == 1 and (nx, ny) not in seen:
                        seen.add((nx, ny))
                        todo.append((nx, ny))

            r0 = min(x for x, y in cells)
            r1 = max(x for x, y in cells)
            c0 = min(y for x, y in cells)
            c1 = max(y for x, y in cells)
            if r1-r0 < 2 or c1-c0 < 2:
                continue

            # Target objects have a mostly 1-valued rectangular perimeter.
            perimeter = []
            perimeter += [(r0, y) for y in range(c0, c1+1)]
            perimeter += [(r1, y) for y in range(c0, c1+1)]
            perimeter += [(x, c0) for x in range(r0+1, r1)]
            perimeter += [(x, c1) for x in range(r0+1, r1)]
            coverage = sum(grid[x][y] == 1 for x, y in perimeter) / len(perimeter)
            if coverage < 0.55:
                continue

            center = ((r0+r1)//2, (c0+c1)//2)
            for x in range(r0+1, r1):
                for y in range(c0+1, c1):
                    if grid[x][y] == 0 and (x, y) != center:
                        out[x][y] = 3

            for y in range(c0-1, c1+2):
                for x in (r0-1, r1+1):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == 0:
                        out[x][y] = 2
            for x in range(r0-1, r1+2):
                for y in (c0-1, c1+1):
                    if 0 <= x < h and 0 <= y < w and grid[x][y] == 0:
                        out[x][y] = 2

    return out
